const fs = require('fs');
// Try reading the xlsx as a zip and extracting shared strings + sheet data
const { execSync } = require('child_process');
execSync('cp /workspace/testbed/data/product_inventory.xlsx /tmp/product_inventory.zip');
execSync('mkdir -p /tmp/xlsx && cd /tmp/xlsx && unzip -o /tmp/product_inventory.zip 2>/dev/null');
const shared = fs.readFileSync('/tmp/xlsx/xl/sharedStrings.xml', 'utf8');
const sheet = fs.readFileSync('/tmp/xlsx/xl/worksheets/sheet1.xml', 'utf8');
console.log('=== Shared Strings ===');
console.log(shared);
console.log('=== Sheet1 ===');
console.log(sheet);
"

node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('/workspace/testbed/data/product_inventory.xlsx');
for (const name of wb.SheetNames) {
    console.log('=== Sheet:', name, '===');
    const data = XLSX.utils.sheet_to_json(wb.Sheets[name]);
    data.forEach(r => console.log(JSON.stringify(r)));
}
"

